import assert from 'assert';
import Database from 'better-sqlite3';

async function runTests() {
  console.log("Starting integration tests...");

  // 1. Test GET /forms/contact_form
  console.log("Testing GET /forms/contact_form...");
  const getRes = await fetch("http://localhost:3000/forms/contact_form");
  assert.strictEqual(getRes.status, 200, "GET /forms/contact_form should return 200");
  const html = await getRes.text();

  // Check form element
  assert.ok(html.includes('method="POST"'), "HTML should contain method=\"POST\"");
  assert.ok(html.includes('action="/forms/contact_form/submit"'), "HTML should contain action=\"/forms/contact_form/submit\"");

  // Check fields
  assert.ok(html.includes('type="text"'), "HTML should contain input type=\"text\"");
  assert.ok(html.includes('name="fullName"'), "HTML should contain name=\"fullName\"");
  assert.ok(html.includes('type="number"'), "HTML should contain input type=\"number\"");
  assert.ok(html.includes('name="age"'), "HTML should contain name=\"age\"");
  assert.ok(html.includes('type="checkbox"'), "HTML should contain input type=\"checkbox\"");
  assert.ok(html.includes('name="subscribe"'), "HTML should contain name=\"subscribe\"");

  // Check labels
  assert.ok(html.includes('for="fullName"'), "HTML should contain label for=\"fullName\"");
  assert.ok(html.includes('for="age"'), "HTML should contain label for=\"age\"");
  assert.ok(html.includes('for="subscribe"'), "HTML should contain label for=\"subscribe\"");

  console.log("✅ GET /forms/contact_form passed!");

  // 2. Test GET /forms/non_existent_form
  console.log("Testing GET /forms/non_existent_form...");
  const get404Res = await fetch("http://localhost:3000/forms/non_existent_form");
  assert.strictEqual(get404Res.status, 404, "GET /forms/non_existent_form should return 404");
  console.log("✅ GET /forms/non_existent_form passed!");

  // 3. Test POST /forms/contact_form/submit with URL-encoded body (valid)
  console.log("Testing POST /forms/contact_form/submit (valid URL-encoded)...");
  const postUrlEncodedRes = await fetch("http://localhost:3000/forms/contact_form/submit", {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded"
    },
    body: "fullName=John+Doe&age=30&subscribe=on"
  });
  assert.strictEqual(postUrlEncodedRes.status, 200, "POST with valid URL-encoded body should return 200");
  const postUrlEncodedData = await postUrlEncodedRes.json();
  assert.strictEqual(postUrlEncodedData.success, true);
  assert.ok(typeof postUrlEncodedData.submissionId === 'number');
  const firstSubmissionId = postUrlEncodedData.submissionId;
  console.log(`✅ Valid URL-encoded submission parsed and saved! ID: ${firstSubmissionId}`);

  // 4. Test POST /forms/contact_form/submit with JSON body (valid)
  console.log("Testing POST /forms/contact_form/submit (valid JSON)...");
  const postJsonRes = await fetch("http://localhost:3000/forms/contact_form/submit", {
    method: "POST",
    headers: {
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      fullName: "Jane Doe",
      age: 25,
      subscribe: false
    })
  });
  assert.strictEqual(postJsonRes.status, 200, "POST with valid JSON body should return 200");
  const postJsonData = await postJsonRes.json();
  assert.strictEqual(postJsonData.success, true);
  assert.ok(typeof postJsonData.submissionId === 'number');
  const secondSubmissionId = postJsonData.submissionId;
  console.log(`✅ Valid JSON submission parsed and saved! ID: ${secondSubmissionId}`);

  // 5. Test POST /forms/contact_form/submit with invalid data (validation failure)
  console.log("Testing POST /forms/contact_form/submit (invalid - age under 18, missing fullName)...");
  const postInvalidRes = await fetch("http://localhost:3000/forms/contact_form/submit", {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded"
    },
    body: "age=12"
  });
  assert.strictEqual(postInvalidRes.status, 400, "POST with invalid data should return 400");
  const postInvalidData = await postInvalidRes.json();
  assert.strictEqual(postInvalidData.success, false);
  assert.deepStrictEqual(postInvalidData.errors, {
    fullName: "fullName is required",
    age: "age must be at least 18"
  });
  console.log("✅ Invalid submission rejected with correct validation errors!");

  // 6. Verify SQLite database persistence
  console.log("Verifying SQLite database persistence...");
  const db = new Database('/home/user/qwik-app/form_builder.sqlite');
  try {
    const rows = db.prepare("SELECT * FROM submissions WHERE form_id = 'contact_form' ORDER BY id ASC").all();
    assert.strictEqual(rows.length >= 2, true, "Should have at least 2 submissions in the database");

    const firstSub = rows.find(r => r.id === firstSubmissionId);
    assert.ok(firstSub, "First submission should exist in DB");
    assert.deepStrictEqual(JSON.parse(firstSub.data), {
      fullName: "John Doe",
      age: 30,
      subscribe: true
    }, "First submission data should match and be parsed correctly");

    const secondSub = rows.find(r => r.id === secondSubmissionId);
    assert.ok(secondSub, "Second submission should exist in DB");
    assert.deepStrictEqual(JSON.parse(secondSub.data), {
      fullName: "Jane Doe",
      age: 25,
      subscribe: false
    }, "Second submission data should match and be parsed correctly");

    console.log("✅ SQLite database verification successful!");
  } finally {
    db.close();
  }

  console.log("\n🎉 ALL TESTS PASSED SUCCESSFULLY! 🎉");
}

runTests().catch(err => {
  console.error("❌ Test failed:", err);
  process.exit(1);
});
